int cmp(const void *x, const void *y) {
    return *(const int *)x - *(const int *)y;
}

right:
#include <stdlib.h>
int cmp(const void *x, const void *y) {
    int a = *(const int *)x;
    int b = *(const int *)y;
    return (a > b) - (a < b);
}
int main(void) {
    int a[] = {3, 1, 2};
    qsort(a, 3, sizeof *a, cmp);
    return a[0] == 1 && a[2] == 3 ? 0 : 1;
}

